# One-shot amendment of the specs for the quality pass of the client space (D-099, 11/10/2026).
#   PYTHONUTF8=1 python Dev/specs-pass-espace-client.py   (refuses to run twice)
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent / 'Specs'


def edit(rel, pairs):
    p = ROOT / rel
    s = p.read_text(encoding='utf-8')
    for old, new in pairs:
        if new.strip() and new in s:
            print('already applied:', rel)
            return
        if old not in s:
            print('MISSING in', rel, ':', old[:90])
            sys.exit(1)
        s = s.replace(old, new, 1)
    p.write_text(s, encoding='utf-8', newline='\n')
    print('edited', rel)


